import { GameScene } from "../GameScene";

var raycaster: any;
var ray: any;
var graphics: any;
var obstacles: any;
var intersections: any;
var fow: any;
var maskGraphics: any;
var mask: any;

export class Raycaster {
  constructor(scene: GameScene) {
    var bounds = new Phaser.Geom.Rectangle(200, 200, 600, 1080);
    raycaster = scene.raycasterPlugin.createRaycaster({
      boundingBox: bounds,
      //  scene.add.rectangle(370, 370, 300, 300, 0x00ffff, 0.0),
    });
    ray = raycaster.createRay({
      origin: {
        x: 370,
        y: 370,
      },
    });

    obstacles = scene.add.group();
    createObstacles(scene);

    raycaster.mapGameObjects(obstacles.getChildren());
    intersections = ray.castCircle();
    graphics = scene.add.graphics({
      lineStyle: { width: 1, color: 0x00ff00, alpha: 0 },
      fillStyle: { color: 0xffffff, alpha: 0 },
    });
    // raycaster.setBoundingBox(70, 70, 300, 300);

    createFOV(scene);
    draw();

    //redraw on mouse move
    // scene.input.on("pointermove", function (pointer: any) {
    //   //set ray position
    //   ray.setOrigin(pointer.x, pointer.y);
    //   console.log(pointer.x, pointer.y);

    //   //cast ray in all directions
    //   intersections = ray.castCircle();
    //   //redraw
    //   draw();
    // });
  }
}

function createFOV(scene: GameScene) {
  maskGraphics = scene.add.graphics({
    fillStyle: { color: 0xffffff, alpha: 0 },
  });
  mask = new Phaser.Display.Masks.GeometryMask(scene, maskGraphics);
  mask.setInvertAlpha();
  fow = scene.add
    .graphics({ fillStyle: { color: 0x000000, alpha: 0.25 } })
    .setDepth(2);
  fow.setMask(mask);
  fow.fillRect(0, 0, 800, 600);
}

function createObstacles(scene: GameScene) {
  //create rectangle obstacle
  let obstacle: any = scene.add
    .rectangle(365, 300, 16, 16)
    .setStrokeStyle(1, 0xffff00);
  obstacle.alpha = 0;
  obstacles.add(obstacle, true);

  obstacle = scene.add.rectangle(460, 370, 16, 16).setStrokeStyle(1, 0xffff00);
  obstacle.alpha = 0;
  obstacles.add(obstacle, true);

  obstacle = scene.add.rectangle(335, 420, 24, 16).setStrokeStyle(1, 0xffff00);
  obstacle.alpha = 0;
  obstacles.add(obstacle, true);
}

function draw() {
  //clear ray visualisation
  graphics.clear();

  //clear field of view mask
  maskGraphics.clear();
  //draw fov mask
  maskGraphics.fillPoints(intersections);

  /*
  graphics.fillStyle(0xffffff, 0.3);
  graphics.fillPoints(intersections);
  */
  //draw rays
  graphics.lineStyle(1, 0x00ff00);
  graphics.alpha = 0;
  for (let intersection of intersections) {
    graphics.strokeLineShape({
      x1: ray.origin.x,
      y1: ray.origin.y,
      x2: intersection.x,
      y2: intersection.y,
    });
  }
  /*
  let raycasterMap = tilemapLayer.data.get('raycasterMap');
  //draw tilemap's segments
  graphics.lineStyle(1, 0xff0000);
  let segments = raycasterMap.getSegments(ray);
  for(let segment of segments) {
    graphics.strokeLineShape(segment);
  }
  */
  graphics.fillStyle(0xff00ff);
  /*
  //draw tilemap's points
  let points = raycasterMap.getPoints(ray);
  for(let point of points) {
    graphics.fillPoint(point.x, point.y, 3);
  }
  */
  //draw ray origin
  graphics.fillPoint(ray.origin.x, ray.origin.y, 3);
}
